"""Commercial Agent: pricing, cost assumptions and DRAFT policies (not legal advice)."""

from __future__ import annotations

from typing import Any

from app.agents.base import AgentContext, BaseAgent
from app.schemas.agent_io import CommercialPack
from app.services.context import plan_context

DRAFT_BANNER = (
    "DRAFT — generated by Mate for review. This is not legal advice. Have a qualified lawyer in {region} "
    "review it before use."
)


def render_policies(pack: CommercialPack, product_name: str) -> dict[str, str]:
    s = pack.policy_specifics
    banner = DRAFT_BANNER.format(region=s.governing_region)
    data = "\n".join(f"- {item}" for item in s.data_collected)
    return {
        "terms": f"""> {banner}

# Terms of Service — {product_name} (draft)

1. **The service.** {product_name} is provided as described on its product page. Features may change; material changes will be announced in advance.
2. **Accounts and access.** Access is granted to the purchasing customer. Access keys must not be shared outside the customer's organisation.
3. **Payment.** Prices are shown before purchase. [Payment processing is not implemented; any checkout in this build is MOCKED.]
4. **Acceptable use.** Do not use the service to store unlawful content or other people's data without permission.
5. **No guarantees of results.** The service is a tool; it does not guarantee any business, academic or financial outcome.
6. **Liability.** [To be completed with legal review for {s.governing_region}.]
7. **Contact.** {s.support_channel}
""",
        "privacy": f"""> {banner}

# Privacy Policy — {product_name} (draft)

**Data collected**
{data}

**How it is used:** only to provide the service and support. It is not sold.

**Where it is stored:** [to be confirmed — the generated MVP stores records in the user's own browser].

**Your rights:** request access, correction or deletion through {s.support_channel}. [Confirm the applicable data-protection law for {s.governing_region} with a lawyer.]
""",
        "refunds": f"""> {banner}

# Refund Policy — {product_name} (draft)

- Refunds can be requested within **{s.refund_window_days} days** of purchase through {s.support_channel}.
- When a refund is issued, access to the product is revoked.
- [In this build refunds are MOCKED: no money moves.]
""",
    }


class CommercialAgent(BaseAgent):
    name = "commercial"
    prompt_file = "commercial.md"
    tools = ("read:plan", "read:product_spec", "calc:break_even")
    responsibility = "Propose pricing, cost assumptions, policy specifics and a compliance checklist."

    def propose(self, ctx: AgentContext, *, plan_document: dict[str, Any], spec_summary: str, budget: str, currency: str) -> CommercialPack:
        content = (
            plan_context(plan_document)
            + f"\n\nMVP: {spec_summary}\nFOUNDER BUDGET: {budget}\nCURRENCY: {currency}\n\n"
            "Propose pricing consistent with the accepted revenue model, list every cost as an explicit assumption in "
            f"{currency}, give policy specifics and a compliance review checklist. Do not promise revenue."
        )
        return self.call(ctx, task="propose_commercial_setup", schema=CommercialPack, user_content=content)
